  const terminalRoot = activeInputSlots(phaseBranch.inputs?.SUBSTACK)[0];
  const liveRoot = activeInputSlots(phaseBranch.inputs?.SUBSTACK2)[0];
  const terminalBranch = typeof terminalRoot === 'string' ? target.blocks[terminalRoot] : undefined;
  const terminalCondition = isBlock(terminalBranch)
