    tableStores,
    armedSymbol,
    checksumSymbol,
    indexSymbol,
    rowSymbol,
    ySymbol,
    rhoSymbol,
    witnessSymbol,
    keySymbol,
    oldKeySymbol,
    stepSymbol,
    modulus,
